#!/bin/bash
# uso: tutti.sh [nome_test ...]  (senza argomenti: tutti)
SP=/tmp/claude-0/-home-claude/f97e63d7-0f90-572a-b598-f314f34539ca/scratchpad
bash $SP/avvia_pg.sh
cd $SP/pacchetto; export OPIFEX_SENZA_PM=1 OPIFEX_SENZA_SCHEDA=1 OPIFEX_SENZA_MODELLO_ECONOMICO=1
P="runuser -u postgres -- /usr/lib/postgresql/16/bin/psql -q -h 127.0.0.1 -p 54329 -v ON_ERROR_STOP=1"
reset(){ $P -d postgres -c "DROP DATABASE IF EXISTS agenti_test" -c "CREATE DATABASE agenti_test ENCODING 'UTF8' TEMPLATE template0 LC_COLLATE 'C.UTF-8' LC_CTYPE 'C.UTF-8'" >/dev/null; for f in sql/[0-9]*.sql; do $P -d agenti_test < $f >/dev/null || echo ERRORE $f; done; }
T="${@:-test_collaudo test_gestione test_documenti test_accessi test_dialoghi test_richieste test_aziende test_aggiornamenti test_canali test_utenti test_progetti test_novita test_task test_ip test_memoria test_gmail test_percorsi test_social test_release18 test_registro test_sistema test_allegati_voce test_task_supporto test_memoria_lavoro test_brevo test_plaud test_iniziative test_voce_telegram test_crm test_briefing_manager test_openai_strumenti test_voce_elevenlabs test_sapere test_studi test_progetti_imprese test_trigger test_sviluppo test_pm test_crm_schede test_pwa test_vuote test_robustezza test_salute test_autonomia test_crm_excel test_pm_task test_canva test_costi test_modelli test_dialoghi_brevi test_silenzio test_codici test_documenti_agenti test_sentinelle test_siti test_chat_coda test_lettura_formati test_misure test_modello_economico test_organigramma_3d test_info_database test_scheda_progetto test_ginnasio test_squadre test_custode test_avatar test_custode_backup test_crm_modello test_chat_conv test_aurora_stile test_prompting_token test_stabilita test_crm_cruscotto test_crm_segmenti test_competenze_base test_web_pausa test_attese test_decisioni_2610 test_v1 test_vetro test_editoria test_verticali}"
for t in $T; do reset; echo "== $t"; SP=$SP $SP/venv/bin/python $SP/$t.py 2>&1 | grep -E "^(OK|FALLITO)|TOTALE|Traceback|Error|File \"|assert" | grep -v "^OK" ; done
